// Host-owned handlers dispatch to the bundled, provider-scoped data engine after authorization.
// The independent package never launches processes, resolves credentials or chooses storage.
export const MEDICAL_DATA_TOOLS: ToolDescriptor[] = MEDICAL_ROUTES.map(({ provider, method }) => ({
  id: method,
  connector: provider,
  credentialKeys: [],
  ...methods[method],
  required: (methods[method].input.required as string[] | undefined) ?? [],
  returns:
    'Provider-scoped JSON. Downloads, imports and extraction return {job_id,status,next_tool}; poll get_job until ready/error. query_local returns bounded metadata and a local CSV path; patient rows remain local. provider_info documents formats, paths, access and limits. Errors are not empty data.',
  run: async () => {
    throw new Error('This tool requires the bundled medical data engine host handler.')
  }
}))
